:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-fog-wash: #fafafa;
  --color-mist-tile: #f0f0f0;
  --color-frosted-glass: #ffffff66;
  --color-onyx: #000000;
  --color-jet-ink: #141414;
  --color-graphite-heading: #313232;
  --color-slate-body: #545454;
  --color-ash-caption: #707070;
  --color-pebble-muted: #949494;
  --color-quartz-border: #c9c9c9;
  --color-dove-hairline: #0000001a;
  --color-emerald-signal: #009959;

  /* Typography — Font Families */
  --font-poppins: "Poppins", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-inter-variable: "Inter Variable", "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 13px;
  --leading-small: 1.23;
  --tracking-small: 0px;
  --text-caption: 14px;
  --leading-caption: 1.43;
  --tracking-caption: 0px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.43;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-body-lg: 18px;
  --leading-body-lg: 1.5;
  --tracking-body-lg: -0.36px;
  --text-subheading: 18px;
  --leading-subheading: 1.6;
  --tracking-subheading: -0.54px;
  --text-heading-sm: 20px;
  --leading-heading-sm: 1.6;
  --tracking-heading-sm: -0.4px;
  --text-heading: 28px;
  --leading-heading: 1.6;
  --tracking-heading: 0px;
  --text-heading-lg: 42px;
  --leading-heading-lg: 1.25;
  --tracking-heading-lg: 0px;
  --text-display: 60px;
  --leading-display: 1.04;
  --tracking-display: -1px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-28: 28px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-60: 60px;
  --spacing-72: 72px;
  --spacing-80: 80px;
  --spacing-96: 96px;

  /* Layout */
  --layout-page-max-width: 1200px;
  --layout-section-gap: 96px;
  --layout-card-padding: 32px;
  --layout-element-gap: 16px;

  /* Border Radius */
  --radius-sm: 3px;
  --radius-sm-2: 6px;
  --radius-md: 8px;
  --radius-md-2: 10px;
  --radius-lg: 12px;
  --radius-lg-2: 14px;
  --radius-xl: 16px;
  --radius-2xl: 24px;
  --radius-full: 50%;

  /* Named Radii */
  --radius-sections: 3px;
  --radius-tags: 6px;
  --radius-badges: 6px;
  --radius-buttons: 8px;
  --radius-small-elements: 10px;
  --radius-inner-tiles: 12px;
  --radius-images: 14px;
  --radius-small-cards: 16px;
  --radius-cards: 24px;
  --radius-avatars: 50%;

  /* Shadows */
  --shadow-subtle: rgba(16, 24, 40, 0.04) 0px 1px 2px 0px;
  --shadow-subtle-2: rgba(0, 0, 0, 0.05) 0px 0px 12px 0px inset;
  --shadow-sm: rgba(0, 0, 0, 0.04) 0px 4px 8px 0px;
  --shadow-md: rgba(0, 0, 0, 0.08) 0px 4px 16px 0px;

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-fog-wash: #fafafa;
  --surface-mist-tile: #f0f0f0;
  --surface-frosted-glass: #ffffff66;
}

